/* @lc app=leetcode id=3725 lang=kotlin */ class Solution { fun mu(d: Int): Int = (2..d).filter { d % it == 0 && (2 until it).none { q -> it % q == 0 } }.let { ps -> if (ps.any { d % (it * it) == 0 }) 0 else if (ps.size % 2 == 0) 1 else -1 } fun countCoprime(mat: Array<IntArray>): Int = ((1..150).sumOf { d -> mu(d) * mat.fold(1L) { acc, row -> acc * row.count { it % d == 0 } % 1_000_000_007L } } % 1_000_000_007L + 1_000_000_007L).let { (it % 1_000_000_007L).toInt() } }